import { isDisclaimerTextColor, normalizeColor } from '@/utils/textColor';

const DISCLAIMER_STYLE_MARKERS = [
  'font-size:14px',
  'line-height:22px',
];

function compactStyle(style: string): string {
  return style.toLowerCase().replace(/\s/g, '');
}

export function isLegacyDisclaimerElement(element: Element): boolean {
  const style = compactStyle(element.getAttribute('style') || '');

  if (element.getAttribute('data-disclaimer') === 'true') {
    return true;
  }

  return (
    DISCLAIMER_STYLE_MARKERS.every(marker => style.includes(marker)) &&
    (
      style.includes('color:#785f5f') ||
      style.includes('color:rgb(120,95,95)')
    )
  );
}

function isDisclaimerTextStyleMark(mark: { type?: string, attrs?: { color?: unknown } }): boolean {
  return mark.type === 'textStyle' && isDisclaimerTextColor(mark.attrs?.color);
}

function cleanNode(node: unknown): unknown {
  if (Array.isArray(node)) {
    return node.map(cleanNode);
  }

  if (!node || typeof node !== 'object') {
    return node;
  }

  const draft = { ...(node as Record<string, unknown>) };

  if (Array.isArray(draft.marks)) {
    const hasDisclaimerMark = draft.marks.some(mark => (
      !!mark &&
      typeof mark === 'object' &&
      (mark as { type?: string }).type === 'strike'
    ));

    if (hasDisclaimerMark) {
      draft.marks = draft.marks.filter(mark => (
        !mark ||
        typeof mark !== 'object' ||
        !isDisclaimerTextStyleMark(mark as { type?: string, attrs?: { color?: unknown } })
      ));
    }
  }

  if (Array.isArray(draft.content)) {
    draft.content = draft.content.map(cleanNode);
  }

  return draft;
}

export function normalizeTextEditorContent(content: unknown): unknown {
  if (!content || typeof content === 'string') {
    return content;
  }

  return cleanNode(content);
}

export function parseTextStyleColor(element: HTMLElement): { color: string } | null {
  if (isLegacyDisclaimerElement(element)) {
    return null;
  }

  const color = normalizeColor(element.style.color);

  if (!color || isDisclaimerTextColor(color)) {
    return null;
  }

  return { color };
}
