import IElement from "@/types/elements/IElement";
import {Element_Type} from "@/types/elements/ElementTypes";

export default class Element implements IElement {
    active = false;
    id: string;
    type: Element_Type;
    options: { [key: string]: any };
    subElements?: Element[];
    constructor(id: string, type: Element_Type, options: { [key: string]: any }, subElements?: Element[], active = false)  {
        this.id = id;
        this.type = type;
        this.options = options;
        this.subElements = subElements;
        this.active = active;
    }
}
