export interface TextColorOption {
  label: string;
  value: string;
}

export const DEFAULT_TEXT_COLOR = '#ff5f00';

export const TEXT_COLORS: TextColorOption[] = [
  { label: 'Orange', value: '#ff5f00' },
  { label: 'Green', value: '#28a3af' },
  { label: 'Purple', value: '#c5569a' },
  { label: 'Yellow', value: '#fdc92a' },
  { label: 'Tangerine', value: '#ff9100' },
];

// Browsers normalize a style attribute's color to rgb(...) when it's read back off an element
// (e.g. after reloading legacy content saved as HTML), so any hex color and its rgb equivalent
// must be treated as the same color or the highlight stops being recognized as active.
export function normalizeColor(color: unknown): string | null {
  if (!color) return null;

  const cleaned = String(color).replace(/['"]+/g, '').replace(/\s+/g, ' ').trim().toLowerCase();

  const rgbMatch = cleaned.match(/^rgba?\(([\d.]+)[, ]+([\d.]+)[, ]+([\d.]+)/);
  if (rgbMatch) {
    const [r, g, b] = rgbMatch.slice(1, 4).map(component => Math.round(Number(component)));
    return '#' + [r, g, b].map(component => component.toString(16).padStart(2, '0')).join('');
  }

  return cleaned;
}

export function isDisclaimerTextColor(color: unknown): boolean {
  return normalizeColor(color) === '#785f5f';
}
